// === ESTRUCTURA DEL PATRÓN BRIDGE ===

// 1. Implementación (el dispositivo)
interface Device {
  turnOn(): void;
  turnOff(): void;
  setChannel(channel: number): void;
  getStatus(): string;
}

// Implementaciones Concretas
class TV implements Device {
  private on = false;
  private channel = 1;
  turnOn() { this.on = true; console.log('TV encendida'); }
  turnOff() { this.on = false; console.log('TV apagada'); }
  setChannel(ch: number) { this.channel = ch; }
  getStatus() { return `TV ${this.on ? 'ON' : 'OFF'} - Canal ${this.channel}`; }
}

class Radio implements Device {
  private on = false;
  private frequency = 88.5;
  turnOn() { this.on = true; console.log('Radio encendida'); }
  turnOff() { this.on = false; console.log('Radio apagada'); }
  setFrequency(freq: number) { this.frequency = freq; }
  getStatus() { return `Radio ${this.on ? 'ON' : 'OFF'} - ${this.frequency}MHz`; }
}

// 2. Abstracción (el control remoto)
abstract class RemoteControl {
  constructor(protected device: Device) {}

  abstract togglePower(): void;
  abstract nextChannel(): void;
}

// 3. Abstracción Refinada
class AdvancedRemote extends RemoteControl {
  private channel = 1;

  togglePower() {
    // Lógica de encendido/apagado con lógica adicional
  }

  nextChannel() {
    this.channel++;
    this.device.setChannel(this.channel);
  }

  setChannel(ch: number) {
    this.channel = ch;
    this.device.setChannel(ch);
  }
}

// Uso:
const tv = new TV();
const remote = new AdvancedRemote(tv);
remote.togglePower();
remote.nextChannel();

